class RoroFile extends RoroElement{filenameLabelTemplate;filenameLabelContainer;wrapper;constructor(e=null){super("file",e,"",{},!1);let i=this;i.ready.then(function(){i.init(),i.registerEvents()})}init(){this.wrapper=this.elt.closest(".roro-wrapper"),this.filenameLabelTemplate=this.wrapper.find(".roro-file-name"),this.filenameLabelContainer=this.wrapper.find(".roro-file-name-container")}registerEvents(){if(this.filenameLabelTemplate){let e=this;e.elt.on("change",function(){e.filenameLabelContainer.empty(),Array.from(this.files).forEach(function(i,n){let t=e.filenameLabelTemplate.clone();t.show(),t.find(".roro-file-name-text").text(i.name),t.find(".roro-file-name-delete").on("click",function(){let i=new DataTransfer;Array.from(e.elt[0].files).forEach((e,t)=>{t!==n&&i.items.add(e)}),e.elt[0].files=i.files,t.remove()}),t.appendTo(e.filenameLabelContainer)})})}}}window.RoroFile=RoroFile;